-- FY2023 revenue for Celsius Coffee Sdn Bhd, on the BANKED (GL) lens.
--
-- WHY A SEPARATE TABLE, AND WHY *NOT* IN unified_sales
-- unified_sales is till truth: what the registers rang up, per outlet. FY2023
-- has no till data and no outlet dimension anywhere — the only surviving record
-- is the company's Bukku "Sales" account ledger, which is the BANKED lens
-- (settlement-lagged, SST-inclusive, and it includes wholesale/B2B and
-- consignment settlements that never touch a Celsius till). Pushing it into
-- unified_sales would silently corrupt every till-based dashboard, the labour
-- gate and the ads guard, all of which assume one consistent lens. So it lives
-- in its own table at ENTITY grain and is deliberately NOT joined into the view.
-- The two lenses are not additive; never sum across them.
--
-- SOURCE + RECONCILIATION
-- "Sales Celsius 2023" (Drive id 1VzUqBERujv7I0pK76UaKTEa11aUv0948nvV2YYN9bb4),
-- single tab "Ledger - Sales", 10,605 rows: one Account ("Sales" + a single
-- "Refund"), one Split Account ("Bank"). Two corrections, both evidenced:
--   1. 39 rows carried an Excel-epoch year (1900-02-27/28). Every memo on them
--      references late Feb 2023 — 'HH230227...', 'HH230228...', '20 to 26 feb',
--      'invoice feb' — so day and month were right and only the year was wrong.
--      Remapped to 2023, restoring RM34,830.82 to February.
--   2. The single Refund row (-RM35.70) is retained as a negative.
-- With both applied the year totals RM1,263,790.41, which TIES EXACTLY to the
-- Income figure stated on the ledger's own summary line. 362 trading dates.
--
-- WHAT IT CANNOT DO
--   • No outlet split. One company, one bank account, no outlet dimension —
--     Shah Alam / Nilai / IOI / Putrajaya cannot be separated for FY2023 at any
--     fidelity. Do not attempt to allocate it.
--   • Not comparable to FY2024+ till figures without adjustment: this lens
--     includes wholesale/B2B (~RM125k in 2023) and carries consignment at the
--     ~70% settlement share, whereas the till lens excludes wholesale entirely
--     and records consignment at gross retail.
--   • Entity attribution is as-at-2023, when Celsius Coffee Sdn Bhd was the only
--     company. Conezion Sdn Bhd (inc. 2025-09-25) and Tamarind Sdn Bhd
--     (inc. 2025-08-07) did not exist.
--
-- The pre-2024 CHECK keeps this table in its own era: FY2024 onward has real
-- per-outlet till data (historical_daily_sales + unified_sales), so an entity
-- row after 2023 would mean two answers to the same question.

CREATE TABLE IF NOT EXISTS historical_entity_revenue (
  id            text PRIMARY KEY,
  entity_reg_no text NOT NULL,
  entity_name   text NOT NULL,
  biz_date      date NOT NULL,
  amount        numeric(12,2) NOT NULL,
  txn_count     integer NOT NULL DEFAULT 0,
  lens          text NOT NULL,
  source_ref    text NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT historical_entity_revenue_pre_2024
    CHECK (biz_date < DATE '2024-01-01'),
  CONSTRAINT historical_entity_revenue_lens
    CHECK (lens IN ('banked_gl')),
  CONSTRAINT historical_entity_revenue_day
    UNIQUE (entity_reg_no, biz_date, lens)
);

COMMENT ON TABLE historical_entity_revenue IS
  'Pre-2024 revenue at LEGAL-ENTITY grain on the banked (GL) lens, where no per-outlet till data exists. Deliberately NOT part of unified_sales — that view is till truth and the two lenses are not additive. See migration 20260730_historical_entity_revenue.';
COMMENT ON COLUMN historical_entity_revenue.amount IS
  'Net revenue recognised in the bank/GL Sales account for the day, RM: settlement-lagged, SST-inclusive, and inclusive of wholesale/B2B and consignment settlements.';
COMMENT ON COLUMN historical_entity_revenue.lens IS
  'Measurement basis. banked_gl = bank/GL recognition. Never mix with the till lens in unified_sales.';

CREATE INDEX IF NOT EXISTS historical_entity_revenue_entity_date_idx
  ON historical_entity_revenue (entity_reg_no, biz_date);

ON CONFLICT (entity_reg_no, biz_date, lens) DO NOTHING;
